public inherited sharing class ExchangeRateClient {

    private static final String NAMED_CREDENTIAL_ENDPOINT = 'callout:FB_Exchange_Rates/v1/latest';
    private static final Integer TIMEOUT_MS = 10000;

    private static final Pattern CURRENCY_CODE_PATTERN = Pattern.compile('^[A-Z]{3}$');

    public class ExchangeRateException extends Exception {}

    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        // Normalise inputs
        String normalisedBase = normaliseCode(baseCurrency);
        Map<String, String> normalisedQuotesByOriginal = new Map<String, String>();
        if (quoteCurrencies != null) {
            for (String quote : quoteCurrencies) {
                normalisedQuotesByOriginal.put(quote, normaliseCode(quote));
            }
        }

        // Validate before any callout
        if (!isValidCode(normalisedBase)) {
            throw new ExchangeRateException('Invalid base currency code: ' + baseCurrency);
        }
        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('Quote currency set must not be null or empty.');
        }
        List<String> normalisedQuotes = new List<String>();
        for (String quote : quoteCurrencies) {
            String normalised = normalisedQuotesByOriginal.get(quote);
            if (!isValidCode(normalised)) {
                throw new ExchangeRateException('Invalid quote currency code: ' + quote);
            }
            // Avoid duplicates while preserving requested codes
            if (!normalisedQuotes.contains(normalised)) {
                normalisedQuotes.add(normalised);
            }
        }

        // Build the request
        HttpRequest request = buildRequest(normalisedBase, normalisedQuotes);

        // First call
        HttpResponse response = doCallout(request);

        // Retry once on 503
        if (response.getStatusCode() == 503) {
            response = doCallout(request);
        }

        Integer statusCode = response.getStatusCode();
        if (statusCode != 200) {
            throw new ExchangeRateException(
                'Exchange rate request failed with status code ' + statusCode
            );
        }

        return parseRates(response.getBody(), normalisedQuotes);
    }

    private static HttpRequest buildRequest(String baseCurrency, List<String> quoteCurrencies) {
        HttpRequest request = new HttpRequest();
        request.setEndpoint(NAMED_CREDENTIAL_ENDPOINT);
        request.setMethod('GET');
        request.setHeader('Accept', 'application/json');
        request.setTimeout(TIMEOUT_MS);

        String symbols = String.join(quoteCurrencies, ',');
        request.setEndpoint(
            NAMED_CREDENTIAL_ENDPOINT
            + '?base=' + EncodingUtil.urlEncode(baseCurrency, 'UTF-8')
            + '&symbols=' + EncodingUtil.urlEncode(symbols, 'UTF-8')
        );
        return request;
    }

    private static HttpResponse doCallout(HttpRequest request) {
        Http http = new Http();
        try {
            return http.send(request);
        } catch (System.CalloutException ce) {
            throw new ExchangeRateException('Callout to exchange rate provider failed: ' + ce.getMessage());
        }
    }

    private static Map<String, Decimal> parseRates(String body, List<String> requestedCodes) {
        Map<String, Decimal> result = new Map<String, Decimal>();
        Map<String, Object> parsed;
        try {
            parsed = (Map<String, Object>) JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new ExchangeRateException('Unable to parse exchange rate response body: ' + e.getMessage());
        }

        Object ratesObj = parsed.get('rates');
        if (ratesObj == null || !(ratesObj instanceof Map<String, Object>)) {
            throw new ExchangeRateException('Exchange rate response is missing a valid "rates" object.');
        }
        Map<String, Object> rates = (Map<String, Object>) ratesObj;

        for (String code : requestedCodes) {
            Object rateObj = rates.get(code);
            if (rateObj == null) {
                throw new ExchangeRateException('No rate returned for requested currency code: ' + code);
            }
            Decimal rate;
            try {
                rate = Decimal.valueOf(String.valueOf(rateObj));
            } catch (Exception e) {
                throw new ExchangeRateException(
                    'Invalid rate value for currency code ' + code + ': ' + String.valueOf(rateObj)
                );
            }
            result.put(code, rate);
        }
        return result;
    }

    private static String normaliseCode(String code) {
        return code == null ? null : code.trim().toUpperCase();
    }

    private static Boolean isValidCode(String code) {
        if (code == null) {
            return false;
        }
        Matcher matcher = CURRENCY_CODE_PATTERN.matcher(code);
        return matcher.matches();
    }
}
