/**
 * @description Invocable Apex action for Flow: finds an existing Contact by
 *              email address.
 *
 *              - Matching is case-insensitive; leading/trailing whitespace in
 *                the input email is ignored.
 *              - A blank/null email or no matching contact yields
 *                found = false, contactId = null.
 *              - If several contacts share the email, the one with the
 *                earliest CreatedDate is returned.
 *              - Runs in user mode, so the running user's sharing rules,
 *                CRUD and FLS are enforced. Exactly one SOQL query is
 *                executed per invocation, regardless of batch size.
 */
public with sharing class ContactLookupAction {

    /**
     * @description Input wrapper for the invocable method.
     */
    public class Request {
        @InvocableVariable(required=true label='Email' description='Email address of the contact to look up.')
        public String email;
    }

    /**
     * @description Output wrapper for the invocable method.
     */
    public class Result {
        @InvocableVariable(label='Contact Id' description='Id of the matching contact, or null if none found.')
        public Id contactId;

        @InvocableVariable(label='Found' description='True if a matching contact was found.')
        public Boolean found;
    }

    /**
     * @description Finds contacts by email for a batch of Flow requests.
     * @param requests One request per Flow interview, up to 200 per call.
     * @return Exactly one Result per Request, in the same order.
     */
    @InvocableMethod(
        label='Find Contact by Email'
        description='Finds an existing contact by email address. Case-insensitive match; returns the contact with the earliest CreatedDate if several match.'
    )
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();

        if (requests == null) {
            return results;
        }

        // Pre-seed results in request order so every request always gets an answer.
        Map<Integer, String> indexToNormalizedEmail = new Map<Integer, String>();
        Set<String> normalizedEmails = new Set<String>();

        for (Integer i = 0; i < requests.size(); i++) {
            String normalized = normalizeEmail(requests[i] == null ? null : requests[i].email);
            if (normalized != null) {
                indexToNormalizedEmail.put(i, normalized);
                normalizedEmails.add(normalized);
            }
        }

        // Earliest CreatedDate per email: query ordered ASC, first hit per key wins.
        Map<String, Id> earliestContactIdByEmail = new Map<String, Id>();

        if (!normalizedEmails.isEmpty()) {
            // WITH USER_MODE enforces the running user's sharing, CRUD and FLS.
            // It must appear after the WHERE clause and before ORDER BY.
            for (Contact c : [
                SELECT Id, Email
                FROM Contact
                WHERE Email IN :normalizedEmails
                WITH USER_MODE
                ORDER BY CreatedDate ASC
            ]) {
                String key = normalizeEmail(c.Email);
                if (key != null && !earliestContactIdByEmail.containsKey(key)) {
                    earliestContactIdByEmail.put(key, c.Id);
                }
            }
        }

        // Build results in the same order as the requests.
        for (Integer i = 0; i < requests.size(); i++) {
            Result r = new Result();
            String normalized = indexToNormalizedEmail.get(i);
            if (normalized != null && earliestContactIdByEmail.containsKey(normalized)) {
                r.found = true;
                r.contactId = earliestContactIdByEmail.get(normalized);
            } else {
                r.found = false;
                r.contactId = null;
            }
            results.add(r);
        }

        return results;
    }

    /**
     * @description Trims the input and lower-cases it for case-insensitive
     *              matching. Returns null for blank/null input.
     */
    private static String normalizeEmail(String email) {
        if (email == null) {
            return null;
        }
        String trimmed = email.trim();
        return String.isBlank(trimmed) ? null : trimmed.toLowerCase();
    }
}
