@isTest
private class AddressVerificationServiceTest {

    /**
     * Thrown by the mock when a callout is made that should never happen
     * (used to prove the SKIPPED path performs no callout).
     */
    private class UnexpectedCalloutException extends Exception {}

    /**
     * Configurable mock for the FB_Address_API named credential.
     * Captures the request so tests can assert the API contract, and either
     * returns a configured response or fails fast if a callout should not occur.
     */
    private class AddressApiMock implements HttpCalloutMock {
        private Integer statusCode;
        private String responseBody;
        private Boolean failOnCall;

        // Captured state, asserted by the tests after the callout.
        public HttpRequest capturedRequest;
        public Integer callCount = 0;

        public AddressApiMock(Integer statusCode, String responseBody) {
            this.statusCode = statusCode;
            this.responseBody = responseBody;
            this.failOnCall = false;
        }

        // Use this constructor to guarantee test failure if any callout is attempted.
        public AddressApiMock(Boolean failOnCall) {
            this.statusCode = 200;
            this.responseBody = '{}';
            this.failOnCall = failOnCall;
        }

        public HttpResponse respond(HttpRequest req) {
            callCount++;
            capturedRequest = req;
            if (failOnCall) {
                throw new UnexpectedCalloutException('A callout was made but none was expected.');
            }
            HttpResponse res = new HttpResponse();
            res.setStatusCode(statusCode);
            res.setBody(responseBody);
            res.setHeader('Content-Type', 'application/json');
            return res;
        }
    }

    private static Account makeAccount() {
        return new Account(
            Name = 'Test Account',
            BillingStreet = '1 Main St',
            BillingCity = 'Springfield',
            BillingPostalCode = '12345',
            BillingCountry = 'USA'
        );
    }

    private static String buildResponseBody(String status, Map<String, Object> address) {
        Map<String, Object> body = new Map<String, Object>{ 'status' => status };
        if (address != null) {
            body.put('address', address);
        }
        return JSON.serialize(body);
    }

    private static AddressVerificationService.Result runVerify(AddressApiMock mock, Account acct) {
        Test.setMock(HttpCalloutMock.class, mock);
        Test.startTest();
        AddressVerificationService.Result result = AddressVerificationService.verify(acct);
        Test.stopTest();
        return result;
    }

    // --- SKIPPED path: blank BillingStreet means no callout, status SKIPPED ---

    @isTest
    static void testBlankStreetIsSkippedWithoutCallout() {
        Account acct = makeAccount();
        acct.BillingStreet = '';
        AddressApiMock mock = new AddressApiMock(true);

        Test.setMock(HttpCalloutMock.class, mock);
        Test.startTest();
        AddressVerificationService.Result result = AddressVerificationService.verify(acct);
        Test.stopTest();

        System.assertEquals('SKIPPED', result.status, 'Blank street must yield SKIPPED');
        System.assertEquals(false, result.changed, 'Nothing should be changed for SKIPPED');
        System.assertEquals(0, mock.callCount, 'No callout may be made for a blank street');
    }

    @isTest
    static void testNullStreetIsSkippedWithoutCallout() {
        Account acct = makeAccount();
        acct.BillingStreet = null;
        AddressApiMock mock = new AddressApiMock(true);

        Test.setMock(HttpCalloutMock.class, mock);
        Test.startTest();
        AddressVerificationService.Result result = AddressVerificationService.verify(acct);
        Test.stopTest();

        System.assertEquals('SKIPPED', result.status, 'Null street must yield SKIPPED');
        System.assertEquals(0, mock.callCount, 'No callout may be made for a null street');
    }

    // --- Request contract: method, endpoint, headers, body ---

    @isTest
    static void testRequestMatchesApiContract() {
        Account acct = makeAccount();
        AddressApiMock mock = new AddressApiMock(200, buildResponseBody('VERIFIED', null));

        runVerify(mock, acct);

        HttpRequest req = mock.capturedRequest;
        System.assertEquals('POST', req.getMethod(), 'Request method must be POST');
        System.assertEquals('callout:FB_Address_API/v2/verify', req.getEndpoint(),
            'Request endpoint must be callout:FB_Address_API/v2/verify');
        System.assertEquals('application/json', req.getHeader('Content-Type'),
            'Request must set Content-Type: application/json');

        Map<String, Object> sentBody = (Map<String, Object>) JSON.deserializeUntyped(req.getBody());
        System.assertEquals(4, sentBody.size(), 'Body must contain exactly the four contract fields');
        System.assertEquals('1 Main St', (String) sentBody.get('street'), 'Body street mismatch');
        System.assertEquals('Springfield', (String) sentBody.get('city'), 'Body city mismatch');
        System.assertEquals('12345', (String) sentBody.get('postalCode'), 'Body postalCode mismatch');
        System.assertEquals('USA', (String) sentBody.get('country'), 'Body country mismatch');
    }

    // --- Error handling: non-200 response ---

    @isTest
    static void testNon200ThrowsExceptionContainingStatusCode() {
        Account acct = makeAccount();
        AddressApiMock mock = new AddressApiMock(500, 'server error');
        Test.setMock(HttpCalloutMock.class, mock);

        Test.startTest();
        try {
            AddressVerificationService.verify(acct);
            System.assert(false, 'A non-200 response must throw AddressVerificationException');
        } catch (AddressVerificationService.AddressVerificationException e) {
            System.assert(e.getMessage().contains('500'),
                'Exception message must contain the status code, was: ' + e.getMessage());
        } catch (Exception e) {
            System.assert(false, 'Wrong exception type thrown: ' + e.getTypeName());
        }
        Test.stopTest();
    }

    @isTest
    static void testNon200DoesNotChangeAccount() {
        Account acct = makeAccount();
        AddressApiMock mock = new AddressApiMock(404, 'not found');
        Test.setMock(HttpCalloutMock.class, mock);

        Test.startTest();
        try {
            AddressVerificationService.verify(acct);
            System.assert(false, 'A non-200 response must throw AddressVerificationException');
        } catch (AddressVerificationService.AddressVerificationException e) {
            System.assert(e.getMessage().contains('404'),
                'Exception message must contain the status code, was: ' + e.getMessage());
        }
        Test.stopTest();

        System.assertEquals('1 Main St', acct.BillingStreet, 'Account must be untouched on error');
    }

    // --- VERIFIED response ---

    @isTest
    static void testVerifiedResponse() {
        Account acct = makeAccount();
        AddressApiMock mock = new AddressApiMock(200, buildResponseBody('VERIFIED', null));

        AddressVerificationService.Result result = runVerify(mock, acct);

        System.assertEquals('VERIFIED', result.status, 'Result status must be the response status');
        System.assertEquals(false, result.changed, 'changed must be false for VERIFIED');
        System.assertEquals('1 Main St', acct.BillingStreet, 'BillingStreet must be untouched for VERIFIED');
        System.assertEquals('Springfield', acct.BillingCity, 'BillingCity must be untouched for VERIFIED');
        System.assertEquals('12345', acct.BillingPostalCode, 'BillingPostalCode must be untouched for VERIFIED');
        System.assertEquals('USA', acct.BillingCountry, 'BillingCountry must be untouched for VERIFIED');
    }

    // --- INVALID response ---

    @isTest
    static void testInvalidResponse() {
        Account acct = makeAccount();
        Map<String, Object> address = new Map<String, Object>{
            'street' => '9 Elsewhere Ave',
            'city' => 'Nowhere',
            'postalCode' => '00000',
            'country' => 'Canada'
        };
        AddressApiMock mock = new AddressApiMock(200, buildResponseBody('INVALID', address));

        AddressVerificationService.Result result = runVerify(mock, acct);

        System.assertEquals('INVALID', result.status, 'Result status must be the response status');
        System.assertEquals(false, result.changed, 'changed must be false for INVALID');
        System.assertEquals('1 Main St', acct.BillingStreet, 'BillingStreet must be untouched for INVALID');
        System.assertEquals('Springfield', acct.BillingCity, 'BillingCity must be untouched for INVALID');
        System.assertEquals('12345', acct.BillingPostalCode, 'BillingPostalCode must be untouched for INVALID');
        System.assertEquals('USA', acct.BillingCountry, 'BillingCountry must be untouched for INVALID');
    }

    // --- CORRECTED response ---

    @isTest
    static void testCorrectedResponseOverwritesAllFourFields() {
        Account acct = makeAccount();
        Map<String, Object> address = new Map<String, Object>{
            'street' => '1 Main Street Apt 2',
            'city' => 'Springfield Township',
            'postalCode' => '12345-6789',
            'country' => 'United States'
        };
        AddressApiMock mock = new AddressApiMock(200, buildResponseBody('CORRECTED', address));

        AddressVerificationService.Result result = runVerify(mock, acct);

        System.assertEquals('CORRECTED', result.status, 'Result status must be the response status');
        System.assertEquals(true, result.changed, 'changed must be true for CORRECTED');
        System.assertEquals('1 Main Street Apt 2', acct.BillingStreet, 'BillingStreet must be overwritten');
        System.assertEquals('Springfield Township', acct.BillingCity, 'BillingCity must be overwritten');
        System.assertEquals('12345-6789', acct.BillingPostalCode, 'BillingPostalCode must be overwritten');
        System.assertEquals('United States', acct.BillingCountry, 'BillingCountry must be overwritten');
    }
}
