/**
 * Tests for OpportunityWonHandler, exercised exclusively through DML so that the
 * OpportunityTrigger wiring and every trigger context is covered.
 *
 * Covered behaviour:
 * - Before insert/update: NextStep is set to 'Handover to Customer Success' for newly won
 *   opportunities only (bulk-safe, other opportunities untouched).
 * - After insert/update: exactly one Task per newly won opportunity with Subject
 *   'Customer kick-off', WhatId = opportunity, OwnerId = opportunity owner,
 *   ActivityDate = CloseDate + 7 days, Priority 'High'.
 * - The opportunity's account gets Rating 'Hot' unless it is already 'Hot'.
 * - Already-won opportunities and won -> other stage transitions change nothing.
 * - Bulk safety: a single account SOQL query and aggregate DML per trigger execution.
 */
@isTest
private class OpportunityWonHandlerTest {

    private static final String WON = 'Closed Won';
    private static final String NOT_WON = 'Prospecting';
    private static final String LOST = 'Closed Lost';
    private static final String HANDOVER = 'Handover to Customer Success';
    private static final Date CLOSE_DATE = Date.today().addDays(10);
    private static final Date EXPECTED_KICKOFF = Date.today().addDays(17);

    private static Id otherUserId;

    @testSetup
    private static void makeOtherUser() {
        Profile standardProfile = [SELECT Id FROM Profile WHERE Name = 'Standard User' LIMIT 1];
        String unique = String.valueOf(DateTime.now().getTime());
        User otherUser = new User(
            Alias = 'ho' + unique.substring(unique.length() - 6),
            Email = 'handover.' + unique + '@example.com',
            EmailEncodingKey = 'UTF-8',
            LastName = 'Handover',
            LanguageLocaleKey = 'en_US',
            LocaleSidKey = 'en_US',
            ProfileId = standardProfile.Id,
            TimeZoneSidKey = 'America/Los_Angeles',
            UserName = 'handover.' + unique + '@example.com'
        );
        insert otherUser;
        otherUserId = otherUser.Id;
    }

    // ------------------------------------------------------------- helpers

    private static Account insertAccount(String rating) {
        Account acc = new Account(Name = 'Handover Test Account', Rating = rating);
        insert acc;
        return acc;
    }

    private static Opportunity insertOpportunity(Id ownerId, Id accountId, String stage) {
        Opportunity opp = new Opportunity(
            Name = 'Handover Test Opp',
            StageName = stage,
            CloseDate = CLOSE_DATE,
            OwnerId = ownerId,
            AccountId = accountId
        );
        insert opp;
        return opp;
    }

    private static Opportunity insertOpportunity(Id ownerId, Id accountId) {
        return insertOpportunity(ownerId, accountId, NOT_WON);
    }

    private static Opportunity insertWonOpportunity(Id ownerId, Id accountId) {
        return insertOpportunity(ownerId, accountId, WON);
    }

    private static List<Task> tasksFor(Id oppId) {
        return [SELECT Id, Subject, WhatId, OwnerId, ActivityDate, Priority
                FROM Task WHERE WhatId = :oppId];
    }

    private static Integer taskCount(Id oppId) {
        return [SELECT COUNT() FROM Task WHERE WhatId = :oppId];
    }

    private static Account accountById(Id accId) {
        return [SELECT Id, Rating FROM Account WHERE Id = :accId];
    }

    private static Opportunity oppById(Id oppId) {
        return [SELECT Id, StageName, NextStep FROM Opportunity WHERE Id = :oppId];
    }

    // ------------------------------------------------------- before insert

    @isTest
    private static void testBeforeInsertWonSetsNextStep() {
        Opportunity opp = insertWonOpportunity(UserInfo.getUserId(), null);
        System.assertEquals(HANDOVER, oppById(opp.Id).NextStep,
            'Newly won insert must set NextStep before the record is saved.');
    }

    @isTest
    private static void testBeforeInsertNotWonLeavesNextStepEmpty() {
        Opportunity opp = insertOpportunity(UserInfo.getUserId(), null, NOT_WON);
        System.assertEquals(null, oppById(opp.Id).NextStep,
            'Non-won insert must not set NextStep.');
