/**
 * @description Utility service that returns the active picklist / multi-select
 *              picklist values of any object's field, chosen at runtime.
 *
 *              - Values are returned in the order they are defined on the field.
 *              - Inactive values are excluded.
 *              - Object and field API names are matched case-insensitively.
 *              - All error conditions throw PicklistService.PicklistServiceException.
 *
 * @note        The default-value flag is read by serializing the picklist entry
 *              describe results to JSON and parsing the "defaultValue" key. This
 *              avoids relying on Schema.PicklistEntry methods that are not
 *              available in all Apex API versions, while the JSON representation
 *              of a picklist entry always contains "defaultValue".
 */
public inherited sharing class PicklistService {

    /**
     * @description One active picklist value.
     */
    public class Option {
        /** The API value of the picklist entry. */
        public String value;
        /** The user-facing label of the picklist entry. */
        public String label;
        /** True only for the field's default value. */
        public Boolean isDefault;

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    /**
     * @description Custom exception thrown for every error condition of this service.
     */
    public class PicklistServiceException extends Exception {}

    /**
     * @description Returns the active values of the given picklist or multi-select
     *              picklist field, in the order they are defined on the field.
     *
     * @param objectApiName API name of the object (standard or custom, case-insensitive).
     * @param fieldApiName  API name of the field (case-insensitive).
     * @return List of active Option entries; empty if the field has no active values.
     * @throws PicklistServiceException when either name is null/blank, the object
     *         does not exist, the field does not exist on the object, or the field
     *         is not a picklist / multi-select picklist.
     */
    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        try {
            validateNotBlank(objectApiName, 'Object API name');
            validateNotBlank(fieldApiName, 'Field API name');

            String trimmedObjectName = objectApiName.trim();
            String trimmedFieldName = fieldApiName.trim().toLowerCase();

            Schema.DescribeSObjectResult objectDescribe = resolveObjectDescribe(trimmedObjectName);

            Map<String, Schema.SObjectField> fieldMap = objectDescribe.fields.getMap();
            // Field describe map keys are always lowercase.
            Schema.SObjectField field = fieldMap.get(trimmedFieldName);
            if (field == null) {
                throw new PicklistServiceException(
                    'Field "' + trimmedFieldName + '" does not exist on object "' + trimmedObjectName + '".'
                );
            }

            Schema.DescribeFieldResult fieldDescribe = field.getDescribe();
            Schema.DisplayType fieldType = fieldDescribe.getType();
            if (fieldType != Schema.DisplayType.PICKLIST
                && fieldType != Schema.DisplayType.MULTIPICKLIST) {
                throw new PicklistServiceException(
                    'Field "' + trimmedFieldName + '" on object "' + trimmedObjectName
                    + '" is not a picklist or multi-select picklist.'
                );
            }

            return buildOptions(fieldDescribe);
        } catch (PicklistServiceException e) {
            throw e;
        } catch (Exception e) {
            // Defensive: guarantee this service never leaks another exception type.
            throw new PicklistServiceException(
                'Unexpected error resolving picklist options: ' + e.getMessage()
            );
        }
    }

    /**
     * @description Builds the list of active options from the field describe result.
     *              The serialized JSON of the picklist entries preserves the order
     *              defined on the field and includes the "active" and "defaultValue"
     *              keys for every entry.
     */
    private static List<Option> buildOptions(Schema.DescribeFieldResult fieldDescribe) {
        List<Option> result = new List<Option>();

        // Serializing the entries keeps their defined order and exposes the
        // "active" and "defaultValue" flags without relying on PicklistEntry
        // methods that are unavailable in some API versions.
        String entriesJson = JSON.serialize(fieldDescribe.getPicklistValues());
        List<Object> entries = (List<Object>) JSON.deserializeUntyped(entriesJson);

        for (Object entryObj : entries) {
            Map<String, Object> entry = (Map<String, Object>) entryObj;

            Boolean active = entry.get('active') == null
                ? false
                : (Boolean) entry.get('active');
            if (!active) {
                continue;
            }

            Boolean defaultValue = entry.get('defaultValue') == null
                ? false
                : (Boolean) entry.get('defaultValue');

            String value = entry.get('value') == null ? null : String.valueOf(entry.get('value'));
            String label = entry.get('label') == null ? null : String.valueOf(entry.get('label'));

            result.add(new Option(value, label, defaultValue));
        }

        return result;
    }

    /**
     * @description Resolves the object API name (case-insensitive) to its describe result.
     */
    private static Schema.DescribeSObjectResult resolveObjectDescribe(String objectApiName) {
        // Keys of the global describe map are lowercase, so lowercasing makes the
        // lookup case-insensitive for both standard and custom objects.
        Schema.SObjectType sObjectType = Schema.getGlobalDescribe().get(objectApiName.toLowerCase());
        if (sObjectType == null) {
            throw new PicklistServiceException('Object "' + objectApiName + '" does not exist.');
        }
        return sObjectType.getDescribe();
    }

    /**
     * @description Ensures the given API name is neither null nor blank.
     */
    private static void validateNotBlank(String apiName, String nameDescription) {
        if (apiName == null || apiName.trim().length() == 0) {
            throw new PicklistServiceException(nameDescription + ' must not be null or blank.');
        }
    }
}
