/**
 * Re-rates up to 50,000 Accounts on demand by chaining Queueable executions.
 *
 * Each execution:
 *  - takes the first 200 Ids from its list,
 *  - runs exactly one SOQL query and one DML statement,
 *  - sets Rating from AnnualRevenue (>= 1,000,000 -> Hot, >= 100,000 -> Warm,
 *    anything else including blank -> Cold),
 *  - enqueues a new AccountScoringJob with the remaining Ids (chaining is NOT
 *    skipped while a test is running, so a single startTest/stopTest block
 *    verifies the whole chain).
 */
public with sharing class AccountScoringJob implements Queueable {

    private static final Integer BATCH_SIZE = 200;
    private static final String RATING_HOT = 'Hot';
    private static final String RATING_WARM = 'Warm';
    private static final String RATING_COLD = 'Cold';
    private static final Decimal HOT_THRESHOLD = 1000000;
    private static final Decimal WARM_THRESHOLD = 100000;

    private final List<Id> accountIds;

    /**
     * @param accountIds the full list of Account Ids to rate; may be null.
     */
    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = accountIds == null ? new List<Id>() : accountIds;
    }

    /**
     * Entry point for the button/controller. Enqueues the first job of the chain.
     *
     * @param accountIds Account Ids to rate.
     * @return the job Id of the first chained job, or null when nothing to do.
     */
    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return System.enqueueJob(new AccountScoringJob(accountIds));
    }

    /**
     * Processes the first 200 Ids, then chains the next job if Ids remain.
     * The QueueableContext parameter is intentionally unused so the job can
     * also be executed directly via execute(null) in unit tests.
     */
    public void execute(QueueableContext context) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        List<Id> batchIds = new List<Id>();
        List<Id> remainingIds = new List<Id>();

        // Apex List has no subList(), so split manually.
        for (Integer i = 0; i < accountIds.size(); i++) {
            if (i < BATCH_SIZE) {
                batchIds.add(accountIds[i]);
            } else {
                remainingIds.add(accountIds[i]);
            }
        }

        // Exactly one SOQL query per execution.
        List<Account> accounts = [
            SELECT Id, AnnualRevenue
            FROM Account
            WHERE Id IN :batchIds
        ];

        for (Account acc : accounts) {
            acc.Rating = determineRating(acc.AnnualRevenue);
        }

        // Exactly one DML statement per execution.
        update accounts;

        // Chain the next batch. Do not skip this when a test is running:
        // the whole chain must execute (and be verified) inside a single
        // Test.startTest()/Test.stopTest() block.
        if (!remainingIds.isEmpty()) {
            System.enqueueJob(new AccountScoringJob(remainingIds));
        }
    }

    private static String determineRating(Decimal annualRevenue) {
        if (annualRevenue == null) {
            return RATING_COLD;
        }
        if (annualRevenue >= HOT_THRESHOLD) {
            return RATING_HOT;
        }
        if (annualRevenue >= WARM_THRESHOLD) {
            return RATING_WARM;
        }
        return RATING_COLD;
    }
}
