trigger OpportunityTrigger on Opportunity (after insert, after update, after delete, after undelete) {
    // All logic lives in the handler so it can be unit-tested and reused.
    // Recalculation happens in "after" events only, so the database already
    // reflects the current DML statement before totals are computed. This keeps
    // the accounts correct even when the same records are modified by several
    // DML statements in one transaction (e.g. a Flow followed by Apex).
    if (Trigger.isDelete) {
        OpportunityPipelineHandler.recalculateAccounts(Trigger.old);
    } else if (Trigger.isUpdate) {
        OpportunityPipelineHandler.recalculateAccounts(Trigger.new, Trigger.oldMap);
    } else {
        // after insert and after undelete
        OpportunityPipelineHandler.recalculateAccounts(Trigger.new);
    }
}
