/**
 * Keeps Account.FB_Open_Pipeline__c (sum of the Amount of open Opportunities)
 * and Account.FB_Open_Opportunities__c (count of open Opportunities) up to date.
 *
 * Design notes:
 * - Totals are always recalculated from the database, not from Trigger.new/old,
 *   so they are correct after every DML statement in a transaction, including
 *   several DML statements on the same records (Flow + Apex, test methods...).
 * - Only accounts actually affected by the current DML statement are recalculated,
 *   which keeps bulk data loads of 200+ opportunities well inside governor limits
 *   (a fixed number of queries and one Account DML per statement).
 * - On update, recalculation only happens when a relevant field changed:
 *   AccountId (the opportunity moved, so both accounts are affected), Amount,
 *   or IsClosed (which also covers stage changes between open and closed stages).
 * - Accounts left with no open opportunities are explicitly set to 0 and 0,
 *   never left blank.
 * - When this handler updates an Account, the legacy AccountTrigger copies the
 *   Rating onto the open opportunities, which re-fires this trigger. That second
 *   pass changes no total-relevant field, so it performs no account DML and the
 *   chain terminates (no recursion guard needed, no stale static state).
 */
public inherited sharing class OpportunityPipelineHandler {

    private static final String PIPELINE_FIELD = 'FB_Open_Pipeline__c';
    private static final String COUNT_FIELD = 'FB_Open_Opportunities__c';

    /**
     * Recalculates every account referenced by the given opportunities.
     * Used for after insert, after undelete and after delete.
     */
    public static void recalculateAccounts(List<Opportunity> opportunities) {
        if (opportunities == null || opportunities.isEmpty()) {
            return;
        }
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity opp : opportunities) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        }
        process(accountIds);
    }

    /**
     * Recalculates the affected accounts for an update, but only when a field that
     * can influence the totals changed. If the opportunity moved to another account,
     * both the old and the new account are recalculated.
     */
    public static void recalculateAccounts(List<Opportunity> newOpps, Map<Id, Opportunity> oldMap) {
        if (newOpps == null || newOpps.isEmpty() || oldMap == null) {
            return;
        }
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity newOpp : newOpps) {
            Opportunity oldOpp = oldMap.get(newOpp.Id);
            Boolean relevantChange = oldOpp == null
                || newOpp.AccountId != oldOpp.AccountId
                || newOpp.Amount != oldOpp.Amount
                || newOpp.IsClosed != oldOpp.IsClosed;
            if (relevantChange) {
                if (newOpp.AccountId != null) {
                    accountIds.add(newOpp.AccountId);
                }
                if (oldOpp != null && oldOpp.AccountId != null) {
                    accountIds.add(oldOpp.AccountId);
                }
            }
        }
        process(accountIds);
    }

    /**
     * Computes the open pipeline and open opportunity count per account and writes
     * them back. Accounts are seeded with 0 / 0 so accounts whose last open
     * opportunity disappeared end up with 0 and 0, not blank.
     */
    private static void process(Set<Id> accountIds) {
        accountIds.remove(null);
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Decimal> pipelineByAccount = new Map<Id, Decimal>();
        Map<Id, Integer> countByAccount = new Map<Id, Integer>();
        for (Id accountId : accountIds) {
            pipelineByAccount.put(accountId, 0);
            countByAccount.put(accountId, 0);
        }

        // SUM(Amount) ignores blank amounts, which counts them as 0.
        for (Opportunity opp : [
            SELECT AccountId, Amount
            FROM Opportunity
            WHERE AccountId IN :accountIds AND IsClosed = false
        ]) {
            Decimal amount = opp.Amount == null ? 0 : opp.Amount;
            pipelineByAccount.put(opp.AccountId, pipelineByAccount.get(opp.AccountId) + amount);
            countByAccount.put(opp.AccountId, countByAccount.get(opp.AccountId) + 1);
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Account acc : [
            SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :accountIds
        ]) {
            Decimal pipeline = pipelineByAccount.get(acc.Id);
            Integer openCount = countByAccount.get(acc.Id);

            // Write only when something actually changed. This also makes the
            // interaction with the legacy AccountTrigger terminate cleanly.
            if (acc.FB_Open_Pipeline__c != pipeline || acc.FB_Open_Opportunities__c != openCount) {
                acc.put(PIPELINE_FIELD, pipeline);
                acc.put(COUNT_FIELD, openCount);
                accountsToUpdate.add(acc);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
