public inherited sharing class Opportunities extends fflib_SObjectDomain
{
    public static final String STAGE_CLOSED_WON = 'Closed Won';

    private final Set<Id> m_qualifyingOpportunityIds = new Set<Id>();

    public Opportunities(List<Opportunity> records)
    {
        super((List<sObject>) records);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable
    {
        public fflib_SObjectDomain construct(List<sObject> records)
        {
            return new Opportunities((List<Opportunity>) records);
        }
    }

    /**
     * An opportunity qualifies when it is inserted with StageName = 'Closed Won'.
     */
    public override void onAfterInsert()
    {
        for (Opportunity record : (List<Opportunity>) getRecords())
        {
            if (record.StageName == STAGE_CLOSED_WON)
            {
                m_qualifyingOpportunityIds.add(record.Id);
            }
        }
        startFulfilmentForQualifying();
    }

    /**
     * An opportunity qualifies when its stage changes to 'Closed Won' from any
     * other stage. Opportunities that were already Closed Won do not qualify again.
     */
    public override void onAfterUpdate(Map<Id, sObject> existingRecords)
    {
        for (Opportunity record : (List<Opportunity>) getRecords())
        {
            Opportunity existingRecord = (Opportunity) existingRecords.get(record.Id);
            if (record.StageName == STAGE_CLOSED_WON && existingRecord.StageName != STAGE_CLOSED_WON)
            {
                m_qualifyingOpportunityIds.add(record.Id);
            }
        }
        startFulfilmentForQualifying();
    }

    /**
     * Calls startFulfilment at most once per trigger invocation, and only when
     * at least one opportunity qualifies.
     */
    private void startFulfilmentForQualifying()
    {
        if (m_qualifyingOpportunityIds.isEmpty())
        {
            return;
        }

        IOpportunityFulfilmentService service =
            (IOpportunityFulfilmentService) Application.Service.newInstance(IOpportunityFulfilmentService.class);
        service.startFulfilment(m_qualifyingOpportunityIds);
    }
}
