    public List<Opportunity> selectTopOpenByAccountIds(Set<Id> accountIds, Integer maxRecords) {
        // Nothing to query, or an invalid limit: avoid a broken SOQL statement
        if (accountIds == null || accountIds.isEmpty() || maxRecords == null || maxRecords <= 0) {
            return new List<Opportunity>();
        }

        fflib_QueryFactory queryFactory = queryFactory();

        // Only open opportunities belonging to the given accounts
        queryFactory.setCondition('IsClosed = false AND AccountId IN :accountIds');

        // Highest Amount first, nulls (no Amount) after everything else,
        // ties resolved by earliest CloseDate
        queryFactory.addOrdering('Amount DESC NULLS LAST');
        queryFactory.addOrdering('CloseDate ASC');

        // Parent account Name on top of the selector's standard field list
        queryFactory.addFieldRelationship('Account', 'Name');

        queryFactory.setLimit(maxRecords);

        return (List<Opportunity>) Database.query(queryFactory.toQuery());
    }
