public inherited sharing class OpportunityWinService {
    private static final String STAGE_CLOSED_WON = 'Closed Won';

    /**
     * Marks the given opportunities as Closed Won with CloseDate = today and,
     * for each opportunity actually closed, publishes a Deal_Won__e platform event.
     *
     * The opportunity updates are registered on a single fflib unit of work
     * (from Application.UnitOfWork) and committed once. commitWork() throws if
     * the DML fails, so the event publishing below only ever runs after the
     * opportunity updates have been committed successfully: if saving fails, no
     * Deal_Won__e is published and the exception propagates to the caller.
     *
     * Note: the org's deployed fflib-apex-common version does not expose
     * registerEvent() on fflib_ISObjectUnitOfWork, so the events are published
     * explicitly right after the unit of work has committed, which still
     * guarantees events are only published for saved deals.
     *
     * @param opportunityIds the opportunities to close; null or empty returns 0
     * @return the number of opportunities that were closed (i.e. were not
     *         already at Closed Won)
     */
    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opportunities =
            OpportunitiesSelector.newInstance().selectById(opportunityIds);

        // Records to update and the originally-loaded records backing them
        // (used to source the Amount for the events).
        List<Opportunity> updates = new List<Opportunity>();
        Map<Id, Opportunity> sourceById = new Map<Id, Opportunity>();

        for (Opportunity opportunity : opportunities) {
            // Skip opportunities already at Closed Won.
            if (opportunity.StageName == STAGE_CLOSED_WON) {
                continue;
            }
            updates.add(new Opportunity(
                Id = opportunity.Id,
                StageName = STAGE_CLOSED_WON,
                CloseDate = Date.today()
            ));
            sourceById.put(opportunity.Id, opportunity);
        }

        // Nothing to close: no DML and no events.
        if (updates.isEmpty()) {
            return 0;
        }

        fflib_ISObjectUnitOfWork unitOfWork = Application.UnitOfWork.newInstance();

        // Register the stage/date updates for DML.
        for (Opportunity updateRecord : updates) {
            unitOfWork.registerDirty(updateRecord);
        }

        // Single commit of all updates. If any update fails, commitWork() throws
        // and the exception propagates to the caller before any event is published.
        unitOfWork.commitWork();

        // The updates are committed; publish one Deal_Won__e per closed opportunity.
        List<Deal_Won__e> events = new List<Deal_Won__e>();
        for (Opportunity updateRecord : updates) {
            Opportunity source = sourceById.get(updateRecord.Id);
            events.add(new Deal_Won__e(
                Opportunity_Id__c = String.valueOf(updateRecord.Id),
                Amount__c = source.Amount
            ));
        }
        EventBus.publish(events);

        return updates.size();
    }
}
