public with sharing class LeadContactMatcher {

    /**
     * For each lead, returns the Id of the first contact (in contacts order)
     * whose email matches the lead's email, or null if there is no match.
     *
     * Matching rules:
     *  - Case-insensitive; leading/trailing whitespace is ignored.
     *  - Blank (null, empty, or whitespace-only) emails never match.
     *  - When several contacts share the lead's email, the first one in
     *    contacts order wins (the map is only populated if the key is absent).
     *
     * No SOQL and no DML: operates purely on the lists passed in, so it is
     * safe to call inside the import transaction.
     *
     * Implementation note (doing it differently than a nested loop, and why):
     * at the stated limits (3,000 leads x 3,000 contacts) a nested loop is up
     * to ~9,000,000 string comparisons inside the import transaction, which
     * risks blowing the Apex CPU limit. Indexing the contacts in a
     * Map<String, Id> keyed by the normalized email makes this O(n + m) with
     * identical results and no queries or DML, so I went with the map. The
     * result list is also grown with add() only — it is not pre-sized — so it
     * ends up with exactly one entry per lead, in lead order.
     *
     * @param leads    leads to match; not modified.
     * @param contacts contacts to match against; not modified.
     * @return list parallel to leads, same size and order, contact Id or null.
     */
    public static List<Id> matchByEmail(List<Lead> leads, List<Contact> contacts) {
        // Index the contacts once: normalized email -> Id, first contact wins.
        Map<String, Id> contactIdByEmail = new Map<String, Id>();
        for (Contact contact : contacts) {
            String email = normalizeEmail(contact.Email);
            if (email != null && !contactIdByEmail.containsKey(email)) {
                contactIdByEmail.put(email, contact.Id);
            }
        }

        // One result entry per lead, in lead order (never pre-size the list).
        List<Id> contactIds = new List<Id>();
        for (Lead lead : leads) {
            String leadEmail = normalizeEmail(lead.Email);
            if (leadEmail == null) {
                // Blank lead email never matches.
                contactIds.add(null);
            } else {
                // Map.get returns null when no contact has this email.
                contactIds.add(contactIdByEmail.get(leadEmail));
            }
        }

        return contactIds;
    }

    /**
     * Lowercases and trims an email for comparison purposes only.
     * Returns null for blank input, which never matches anything.
     */
    private static String normalizeEmail(String email) {
        if (String.isBlank(email)) {
            return null;
        }
        return email.trim().toLowerCase();
    }
}
