/**
 * Fires after Case update and schedules CSAT survey tasks for newly closed cases.
 *
 * Design notes:
 * - Only cases transitioning from not-closed to closed are considered, so
 *   edits to an already-closed case do not create duplicate surveys.
 * - Cases without a ContactId are filtered out here; the job re-checks
 *   defensively.
 * - We enqueue a SINGLE Queueable with all qualifying case IDs instead of one
 *   job per case. Salesforce allows at most 50 System.enqueueJob calls per
 *   transaction; bulk closes (list views, nightly API cleanup of up to 200)
 *   would exceed that and throw a LimitException. Per-case isolation is
 *   preserved inside the job via partial-success DML.
 */
trigger CaseTrigger on Case (after update) {
    if (Trigger.isAfter && Trigger.isUpdate) {
        Set<Id> newlyClosedCaseIds = new Set<Id>();

        for (Case newCase : Trigger.new) {
            Case oldCase = Trigger.oldMap.get(newCase.Id);
            if (newCase.IsClosed && !oldCase.IsClosed && newCase.ContactId != null) {
                newlyClosedCaseIds.add(newCase.Id);
            }
        }

        if (!newlyClosedCaseIds.isEmpty()) {
            System.enqueueJob(new CaseSurveyJob(newlyClosedCaseIds));
        }
    }
}
