/**
 * Queueable job that creates CSAT survey Tasks for closed cases.
 *
 * Runs asynchronously (a vendor survey integration is planned, so this step
 * must be free to grow without slowing case saves). Processes each case
 * independently: task creation uses partial-success DML, so a failure on one
 * case's task does not roll back the others.
 */
public inherited sharing class CaseSurveyJob implements Queueable {

    private static final Integer SURVEY_DUE_IN_DAYS = 2;
    private static final String TASK_STATUS = 'Not Started';
    private static final String TASK_SUBJECT_PREFIX = 'CSAT survey: ';

    private final Set<Id> caseIds;

    public CaseSurveyJob(Set<Id> caseIds) {
        this.caseIds = caseIds == null ? new Set<Id>() : caseIds;
    }

    // Signature required by System.Queueable: void execute(QueueableContext).
    public void execute(QueueableContext context) {
        if (caseIds.isEmpty()) {
            return;
        }

        // Re-query in the async context: we need CaseNumber (not available on
        // the trigger record without a query) and the current ContactId.
        Map<Id, Case> casesById = new Map<Id, Case>([
            SELECT Id, CaseNumber, ContactId
            FROM Case
            WHERE Id IN :caseIds
        ]);

        Date dueDate = Date.today().addDays(SURVEY_DUE_IN_DAYS);
        List<Task> surveyTasks = new List<Task>();

        for (Id caseId : caseIds) {
            Case c = casesById.get(caseId);

            // Defensive re-check: the contact could have been cleared between
            // trigger and execution, or the case deleted. Skip silently.
            if (c == null || c.ContactId == null) {
                continue;
            }

            surveyTasks.add(new Task(
                WhatId       = c.Id,
                WhoId        = c.ContactId,
                Subject      = TASK_SUBJECT_PREFIX + c.CaseNumber,
                ActivityDate = dueDate,
                Status       = TASK_STATUS
            ));
        }

        if (surveyTasks.isEmpty()) {
            return;
        }

        // allOrNone = false keeps cases isolated: one bad record fails alone.
        List<Database.SaveResult> results = Database.insert(surveyTasks, false);

        for (Integer i = 0; i < results.size(); i++) {
            if (!results[i].isSuccess()) {
                // Replace with org-standard error handling if desired
                // (e.g., write to a custom error log object).
                for (Database.Error err : results[i].getErrors()) {
                    System.debug(
                        LoggingLevel.ERROR,
                        'CaseSurveyJob: failed to create survey task for case ' +
                        surveyTasks[i].WhatId + ': ' + err.getStatusCode() +
                        ' - ' + err.getMessage()
                    );
                }
            }
        }
    }
}
```

