import { LightningElement, api } from 'lwc';

export default class OrderLinesPanel extends LightningElement {
    /** Array of { key, productName, quantity } */
    @api lines = [];

    showError = false;

    get editors() {
        return this.template.querySelectorAll('c-line-item-editor');
    }

    handleButtonClick(event) {
        const action = event.currentTarget.dataset.action;
        if (action === 'reset') {
            this.handleReset();
        } else if (action === 'submit') {
            this.handleSubmit();
        }
    }

    handleReset() {
        this.showError = false;
        this.editors.forEach((editor) => editor.reset());
    }

    handleSubmit() {
        const editors = this.editors;

        // Validate every editor, even after one fails, so all invalid
        // lines show their errors at once.
        let allValid = true;
        editors.forEach((editor) => {
            const valid = editor.validate();
            if (!valid) {
                allValid = false;
            }
        });

        if (!allValid) {
            this.showError = true;
            return;
        }

        this.showError = false;

        // querySelectorAll returns a NodeList (no .map), so collect the
        // values into a plain array to preserve display order.
        const lines = [];
        editors.forEach((editor) => {
            lines.push(editor.getValue());
        });

        this.dispatchEvent(
            new CustomEvent('submit', {
                detail: { lines },
            })
        );
    }
}
