import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    // Private backing fields. Parent values are never mutated.
    _heading = '';
    _tasks = [];

    // Reactive private state. Arrays are always replaced (never mutated in place)
    // so LWC re-renders reliably.
    items = [];
    newLabel = '';
    nextId = 1;

    // Public API: heading is display only. The parent's value is stored untouched
    // and upper-cased only for rendering, so later changes by the parent show.
    @api
    get heading() {
        return this._heading;
    }

    set heading(value) {
        this._heading = value == null ? '' : value;
    }

    // Public API: whenever the parent passes a new array, the working list is
    // replaced with a copy of it. The parent's array and task objects are never
    // modified.
    @api
    get tasks() {
        return this._tasks;
    }

    set tasks(value) {
        this._tasks = value == null ? [] : value;
        this.items = [...this._tasks];
    }

    connectedCallback() {
        // Take our own copy of the initial list so we never mutate the parent's data.
        this.items = [...this._tasks];
    }

    get headingLabel() {
        return this._heading ? this._heading.toUpperCase() : '';
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const label = (this.newLabel || '').trim();
        if (!label) {
            // Empty or whitespace-only labels are ignored: nothing added, no event.
            return;
        }

        // Replace the array (immutable update) so the change is reactive.
        this.items = [...this.items, { id: `new-${this.nextId++}`, label, done: false }];

        // Dispatch the event with the label that was added.
        this.dispatchEvent(new CustomEvent('taskadded', { detail: { label } }));

        // Clear the input last.
        this.newLabel = '';
    }

    handleToggle(event) {
        const id = event.target.dataset.id;
        const index = this.items.findIndex(
            (task) => String(task.id) === String(id)
        );
        if (index === -1) {
            // Defensive: no error if the id cannot be found.
            return;
        }

        // Immutable update: replace the array and the toggled task object so the
        // checkbox state and the remaining counter re-render. The parent's task
        // objects are never touched.
        this.items = this.items.map((task, i) =>
            i === index ? { ...task, done: !task.done } : task
        );
    }
}
