/**
 * GiftImportService
 *
 * Accepts one-off website gifts and processes them through NPSP's own data
 * import engine (NPSP Data Importer / BDI) so that NPSP's contact matching,
 * household creation and donation processing rules apply.
 *
 * For every gift we stage exactly one npsp__DataImport__c record (which stays
 * in the org as the audit trail of what was imported), run NPSP's data import
 * Apex API synchronously in the same transaction, and then build an
 * ImportResult per gift from the results NPSP wrote back to the staged
 * records.
 *
 * Bulk-safe: a single call may contain up to 200 gifts (staged and processed
 * in bulk, no per-record SOQL/DML inside loops). Rows NPSP rejects are
 * reported individually and never stop the remaining rows from being
 * processed.
 */
public with sharing class GiftImportService {

    /** Status value NPSP writes back to npsp__Status__c for a fully imported row. */
    private static final String STATUS_IMPORTED = 'Imported';

    /** Incoming gift from the website. */
    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    /** Outcome for one gift, in input order. */
    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    /**
     * Stage one NPSP Data Import record per gift, run NPSP's data import
     * synchronously in this transaction, and return one ImportResult per
     * gift, in input order.
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();

        // Null or empty input yields an empty result list.
        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // 1. Stage one npsp__DataImport__c record per gift (bulk DML, single call).
        List<npsp__DataImport__c> stagedRecords = new List<npsp__DataImport__c>();
        for (WebGift gift : gifts) {
            stagedRecords.add(stageGift(gift));
        }

        Boolean stagingSucceeded = true;
        String stagingError;
        try {
            insert stagedRecords;
        } catch Exception e {
            // Staging itself failed (e.g. validation rule on Data Import):
            // report every gift as failed but never blow up the caller.
            stagingSucceeded = false;
            stagingError = 'Unable to stage gifts for NPSP Data Import: ' + e.getMessage();
        }

        if (stagingSucceeded) {
            // 2. Run NPSP's data import engine synchronously, in this
            //    transaction, using the org's Data Import settings
            //    (npsp__Data_Import_Settings__c) for contact matching and
            //    donation processing.
            runNpspDataImport(stagedRecords);

            // 3. Read back what NPSP wrote to the staged records and build
            //    the results in input order.
            Map<Id, npsp__DataImport__c> processedRecords = new Map<Id, npsp__DataImport__c>([
                SELECT Id,
                       npsp__Status__c,
                       npsp__Contact1Imported__c,
                       npsp__DonationImported__c,
                       npsp__FailureInformation__c
                FROM npsp__DataImport__c
                WHERE Id IN :stagedRecords
            ]);

            for (npsp__DataImport__c stagedRecord : stagedRecords) {
                results.add(buildResult(processedRecords.get(stagedRecord.Id)));
            }
        } else {
            for (Integer i = 0; i < gifts.size(); i++) {
                ImportResult result = new ImportResult();
                result.success = false;
                result.errorMessage = stagingError;
                results.add(result);
            }
        }

        return results;
    }

    /**
     * Map a website gift onto NPSP's staging fields. Donor is always the
     * primary contact (Contact1); NPSP's own matching/HH/donation settings
     * decide whether the contact is matched or created.
     */
    private static npsp__DataImport__c stageGift(WebGift gift) {
        npsp__DataImport__c dataImport = new npsp__DataImport__c();
        dataImport.npsp__Contact1_Firstname__c = gift.firstName;
        dataImport.npsp__Contact1_Lastname__c = gift.lastName;
        dataImport.npsp__Contact1_Personal_Email__c = gift.email;
        dataImport.npsp__Donation_Amount__c = gift.amount;
        dataImport.npsp__Donation_Date__c = gift.giftDate;
        dataImport.npsp__Donation_Donor__c = 'Contact1';
        return dataImport;
    }

    /**
     * Invoke NPSP's data import Apex API synchronously (same transaction).
     *
     * NPSP ships its import engine as the batchable class
     * npsp.BDI_DataImportBatchJob. Calling its execute() method directly with
     * the staged records runs NPSP's full import pipeline (contact matching,
     * household creation, donation processing, result write-back) inline,
     * honoring the org's npsp__Data_Import_Settings__c — instead of
     * queueing it asynchronously with Database.executeBatch. NPSP's execute()
     * implementation does not use the BatchableContext, so passing null is
     * safe. Failed rows are caught per row by NPSP itself (Status = 'Failed'
     * plus npsp__FailureInformation__c), so one bad row never stops the rest.
     */
    private static void runNpspDataImport(List<npsp__DataImport__c> dataImports) {
        npsp.BDI_DataImportBatchJob dataImportJob = new npsp.BDI_DataImportBatchJob();
        dataImportJob.execute(null, dataImports);
    }

    /**
     * Build the caller-facing result for one gift from the processed
     * npsp__DataImport__c record.
     */
    private static ImportResult buildResult(npsp__DataImport__c processedRecord) {
        ImportResult result = new ImportResult();

        if (processedRecord == null) {
            result.success = false;
            result.errorMessage = 'NPSP did not process the staged Data Import record.';
            return result;
        }

        result.success = processedRecord.npsp__Status__c == STATUS_IMPORTED;

        if (result.success) {
            // Contact and donation that NPSP matched or created.
            result.contactId = processedRecord.npsp__Contact1Imported__c;
            result.opportunityId = processedRecord.npsp__DonationImported__c;
        } else {
            // Carry NPSP's failure information; fall back to the status
            // NPSP left on the row if the detail field is empty.
            result.errorMessage = String.isNotBlank(processedRecord.npsp__FailureInformation__c)
                ? processedRecord.npsp__FailureInformation__c
                : 'NPSP reported status: ' + (processedRecord.npsp__Status__c == null
                    ? 'not processed'
                    : processedRecord.npsp__Status__c);
        }

        return result;
    }
}
