/**
 * @description Service that records monthly giving sign-ups coming from an external
 * donation form as Enhanced Recurring Donations (NPSP).
 *
 * Design notes:
 * - One SOQL query / one DML statement per call, sized for batches of up to 200 requests.
 * - All input is validated BEFORE any DML is issued, so a single bad request never
 *   leaves partial data behind.
 * - Opportunities (installments) are deliberately NOT created here. With Enhanced
 *   Recurring Donations enabled, NPSP's own trigger/batch generates the installment
 *   Opportunities from the schedule fields on the Recurring Donation.
 * - dayOfMonth 31 is stored using ERD's "always use last day of month" option, so
 *   short months correctly charge on the last day; 29 and 30 are stored as-is.
 */
public inherited sharing class RecurringGiftService {

    public class RecurringGiftException extends Exception {}

    /** Payload for a single monthly-giving sign-up. */
    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;    // 1-31
        public Date startDate;
        public Integer installments;  // null or 0 = no end date
        public String paymentMethod;  // 'Credit Card', 'ACH' or 'Check'

        public GiftRequest() {}
    }

    private static final String INSTALLMENT_PERIOD_MONTHLY = 'Monthly';
    private static final String SCHEDULE_TYPE_FIXED = 'Fixed';
    private static final String RECURRING_TYPE_FIXED = 'Fixed';
    private static final String RECURRING_TYPE_OPEN = 'Open';
    private static final String OPEN_ENDED_STATUS_OPEN = 'Open';
    private static final String STATUS_ACTIVE = 'Active';
    private static final Integer MIN_DAY_OF_MONTH = 1;
    private static final Integer MAX_DAY_OF_MONTH = 31;
    // npsp__InstallmentFrequency__c is a text field in this org.
    private static final String INSTALLMENT_FREQUENCY_MONTHLY = '1';

    /**
     * @description Creates one Enhanced Recurring Donation per request.
     * @param requests The sign-ups to record; may be null or empty.
     * @return The Ids of the newly created npe03__Recurring_Donation__c records,
     *         in the same order as the requests.
     * @throws RecurringGiftService.RecurringGiftException if any request is invalid,
     *         or if the DML fails. No DML is issued until all requests validate.
     */
    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return new List<Id>();
        }

        // Validate everything up-front: no DML happens until all requests pass.
        validateRequests(requests);

        List<npe03__Recurring_Donation__c> recurringDonations = new List<npe03__Recurring_Donation__c>();
        for (GiftRequest request : requests) {
            recurringDonations.add(buildRecurringDonation(request));
        }

        // Single DML statement. NPSP's ERD trigger picks these up and generates the
        // installment Opportunities itself - we must not create Opportunities here.
        insert recurringDonations;

        List<Id> recurringDonationIds = new List<Id>();
        for (npe03__Recurring_Donation__c recurringDonation : recurringDonations) {
            recurringDonationIds.add(recurringDonation.Id);
        }
        return recurringDonationIds;
    }

    /**
     * @description Validates every request before any DML is performed.
     * @param requests The sign-ups to validate; assumed non-empty.
     * @throws RecurringGiftService.RecurringGiftException naming the offending request.
     */
    private static void validateRequests(List<GiftRequest> requests) {
        for (Integer i = 0; i < requests.size(); i++) {
            GiftRequest request = requests[i];
            String context = 'GiftRequest at index ' + i + ': ';

            if (request == null) {
                throw new RecurringGiftException(context + 'request must not be null.');
            }
            if (request.contactId == null) {
                throw new RecurringGiftException(context + 'contactId must not be null.');
            }
            if (request.amount == null || request.amount <= 0) {
                throw new RecurringGiftException(context + 'amount must be a positive number.');
            }
            if (request.dayOfMonth == null
                || request.dayOfMonth < MIN_DAY_OF_MONTH
                || request.dayOfMonth > MAX_DAY_OF_MONTH) {
                throw new RecurringGiftException(context + 'dayOfMonth must be between 1 and 31.');
            }
            if (request.startDate == null) {
                throw new RecurringGiftException(context + 'startDate must not be null.');
            }
            if (request.installments != null && request.installments < 0) {
                throw new RecurringGiftException(context + 'installments must be null, 0 or a positive number.');
            }
        }
    }

    /**
     * @description Maps one validated request to an Enhanced Recurring Donation record.
     * @param request A validated sign-up.
     * @return The in-memory npe03__Recurring_Donation__c record (not yet inserted).
     */
    private static npe03__Recurring_Donation__c buildRecurringDonation(GiftRequest request) {
        npe03__Recurring_Donation__c recurringDonation = new npe03__Recurring_Donation__c(
            npe03__Contact__c = request.contactId,
            npe03__Amount__c = request.amount,
            npe03__Installment_Period__c = INSTALLMENT_PERIOD_MONTHLY,
            // 'Fixed' = each installment is the stated amount (as opposed to
            // 'Divide By' / 'Multiply By' totals). ERD manages open vs. fixed
            // length via npsp__RecurringType__c.
            npe03__Schedule_Type__c = SCHEDULE_TYPE_FIXED,
            npsp__InstallmentFrequency__c = INSTALLMENT_FREQUENCY_MONTHLY,
            npsp__Day_of_Month__c = request.dayOfMonth,
            // "31" means last day of the month, even in short months.
            // 29 and 30 are stored as those literal days.
            npsp__Always_Use_Last_Day_Of_Month__c = (request.dayOfMonth == MAX_DAY_OF_MONTH),
            npsp__StartDate__c = request.startDate,
            npe03__Date_Established__c = Date.today(),
            npe03__Next_Payment_Date__c = request.startDate,
            npsp__Status__c = STATUS_ACTIVE
        );

        if (request.paymentMethod != null) {
            recurringDonation.npsp__PaymentMethod__c = request.paymentMethod;
        }

        if (request.installments == null || request.installments == 0) {
            // Open-ended recurring donation: no fixed number of installments.
            recurringDonation.npsp__RecurringType__c = RECURRING_TYPE_OPEN;
            recurringDonation.npe03__Open_Ended_Status__c = OPEN_ENDED_STATUS_OPEN;
            recurringDonation.npe03__Installments__c = null;
        } else {
            // Fixed-length recurring donation with a known number of installments.
            recurringDonation.npsp__RecurringType__c = RECURRING_TYPE_FIXED;
            recurringDonation.npe03__Installments__c = request.installments;
        }

        return recurringDonation;
    }
}
