/**
 * @description Service for replacing the GAU Allocations on an Opportunity with a
 * percentage-based split across General Accounting Units.
 *
 * Each allocation is stored with BOTH npsp__Amount__c and npsp__Percent__c.
 * Because NPSP persists the percentage on every allocation, NPSP recalculates the
 * allocation amounts proportionally whenever the Opportunity Amount changes later
 * (e.g. a $1,000 gift split 60/40 corrected to $2,000 becomes $1,200 / $800)
 * without any additional code.
 *
 * All validation happens before any DML, and the delete + insert run in the same
 * transaction, so a failure leaves the data untouched.
 */
public inherited sharing class GauAllocationService {

    public class AllocationException extends Exception {}

    private static final Decimal MAX_TOTAL_PERCENT = 100;

    /**
     * @description Replaces all existing GAU Allocations of an Opportunity with one
     *              allocation per map entry, storing both Amount and Percent.
     * @param opportunityId  the Opportunity to allocate
     * @param percentByGauId map of npsp__General_Accounting_Unit__c Id -> percentage
     *                       (60 means 60%). A total below 100% is allowed; the
     *                       remainder stays unallocated.
     * @return the newly inserted npsp__Allocation__c records
     * @throws AllocationException if the input is invalid (null/empty map, null or
     *                       non-positive percentage, total > 100, unknown or
     *                       inactive GAU) or the Opportunity does not exist
     */
    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {
        // ---------------------------------------------------------------
        // Validation (no DML before every check has passed)
        // ---------------------------------------------------------------
        validateInput(percentByGauId);

        Map<Id, npsp__General_Accounting_Unit__c> gausById = new Map<Id, npsp__General_Accounting_Unit__c>(
            [
                SELECT Id, npsp__Active__c
                FROM npsp__General_Accounting_Unit__c
                WHERE Id IN :percentByGauId.keySet()
            ]
        );

        for (Id gauId : percentByGauId.keySet()) {
            if (!gausById.containsKey(gauId)) {
                throw new AllocationException(
                    'No General Accounting Unit found with Id: ' + gauId
                );
            }
            if (gausById.get(gauId).npsp__Active__c != true) {
                throw new AllocationException(
                    'General Accounting Unit is inactive: ' + gauId
                );
            }
        }

        // A SOQL query with a literal Id throws a QueryException if nothing is
        // found, so no explicit null check is needed here.
        Opportunity opp = [
            SELECT Id, Amount
            FROM Opportunity
            WHERE Id = :opportunityId
        ];

        // ---------------------------------------------------------------
        // DML: replace existing allocations in a single transaction
        // ---------------------------------------------------------------
        List<npsp__Allocation__c> existingAllocations = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
        ];
        if (!existingAllocations.isEmpty()) {
            delete existingAllocations;
        }

        List<npsp__Allocation__c> newAllocations = buildAllocations(opp, percentByGauId);
        insert newAllocations;

        return newAllocations;
    }

    /**
     * @description Validates the percentage map. Throws AllocationException on any
     *              invalid value. Percentages must be non-null and > 0, and the
     *              total must not exceed 100.
     */
    private static void validateInput(Map<Id, Decimal> percentByGauId) {
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException(
                'The allocation map must not be null or empty.'
            );
        }

        Decimal totalPercent = 0;

        for (Id gauId : percentByGauId.keySet()) {
            if (gauId == null) {
                throw new AllocationException('GAU Id in the map must not be null.');
            }

            Decimal percent = percentByGauId.get(gauId);
            if (percent == null) {
                throw new AllocationException(
                    'Percentage for GAU ' + gauId + ' must not be null.'
                );
            }
            if (percent <= 0) {
                throw new AllocationException(
                    'Percentage for GAU ' + gauId + ' must be greater than 0.'
                );
            }
            totalPercent += percent;
        }

        if (totalPercent > MAX_TOTAL_PERCENT) {
            throw new AllocationException(
                'Total percentage must not exceed 100. Provided total: ' + totalPercent
            );
        }
    }

    /**
     * @description Builds one allocation per map entry with both Amount and Percent
     *              populated. The persisted Percent is what allows NPSP to keep the
     *              amounts correct when the Opportunity Amount changes later.
     */
    private static List<npsp__Allocation__c> buildAllocations(
        Opportunity opp,
        Map<Id, Decimal> percentByGauId
    ) {
        List<npsp__Allocation__c> allocations = new List<npsp__Allocation__c>();
        Decimal opportunityAmount = opp.Amount == null ? 0 : opp.Amount;

        for (Id gauId : percentByGauId.keySet()) {
            Decimal percent = percentByGauId.get(gauId);

            allocations.add(
                new npsp__Allocation__c(
                    npsp__Opportunity__c = opp.Id,
                    npsp__General_Accounting_Unit__c = gauId,
                    npsp__Percent__c = percent,
                    npsp__Amount__c = (opportunityAmount * percent / 100).setScale(2, RoundingMode.HALF_UP)
                )
            );
        }

        return allocations;
    }
}
