/**
 * @description Service for registering a family (one or more new Contacts) into a
 *              single new NPSP Household Account in one atomic operation.
 *
 *              Design notes:
 *              - The Household Account is created with the NPSP Household record type
 *                (resolved via describe by DeveloperName, never a hard-coded Id) and
 *                WITHOUT a Name. NPSP's Account trigger (Account_Contact_HH_Acc via the
 *                TDTM framework) populates the household Name and the greeting fields,
 *                and re-names the household as Contacts are added. We never set the
 *                Name ourselves.
 *              - Every Contact is inserted with AccountId already pointing at the new
 *                household. Because the Contacts are born inside the household, NPSP's
 *                account-processing logic (e.g. One-to-One auto account creation) never
 *                fires, so no empty/extra accounts are left behind.
 *              - The first Contact in the list is recorded as the household's primary
 *                contact via Account.npe01__One2OneContact__c, after the Contacts exist
 *                so the FK is valid.
 *              - A savepoint guards the whole operation: if anything fails after the
 *                household insert, the household is rolled back so the call never
 *                leaves an orphan/empty account behind.
 *
 *              Bulk-safe: no SOQL or DML inside loops; exactly one insert for the
 *              Account, one insert for all Contacts, one update for the primary contact.
 */
public with sharing class HouseholdService {

    /** DeveloperName of the NPSP Household Account record type in this org. */
    private static final String HOUSEHOLD_RECORD_TYPE_DEV_NAME = 'HH_Account';

    /**
     * @description Creates ONE new NPSP Household Account and inserts all supplied
     *              Contacts into it. NPSP generates the household Name and greetings.
     * @param members New Contacts (no Id, no AccountId required) to place in the
     *                household. The first Contact becomes the household's primary
     *                contact (npe01__One2OneContact__c).
     * @return The Id of the newly created Household Account.
     * @throws IllegalArgumentException if members is null/empty, or if the Household
     *         record type is not available for the running user.
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException(
                'HouseholdService.createHousehold requires a non-empty list of Contacts.'
            );
        }

        Id householdRecordTypeId = getHouseholdRecordTypeId();

        // Roll everything back if any step fails, so no household is ever left behind.
        Savepoint sp = Database.setSavepoint();
        try {
            // Intentionally no Name: NPSP names Household Accounts and generates
            // greetings via its trigger framework.
            Account household = new Account(
                RecordTypeId = householdRecordTypeId
            );
            insert household;

            // Insert all members directly into the household. Cloning keeps any extra
            // field data the caller set, without mutating the caller's list or carrying
            // over an Id.
            List<Contact> contactsToInsert = new List<Contact>();
            for (Contact member : members) {
                Contact toInsert = member.clone(false);
                toInsert.AccountId = household.Id;
                contactsToInsert.add(toInsert);
            }
            insert contactsToInsert;

            // First member is the household's primary contact. This must happen after
            // the Contacts are inserted so the lookup FK is valid; NPSP's Account
            // trigger validates the Contact belongs to this household.
            update new Account(
                Id = household.Id,
                npe01__One2OneContact__c = contactsToInsert[0].Id
            );

            return household.Id;
        } catch (Exception e) {
            Database.rollback(sp);
            throw e;
        }
    }

    /**
     * @description Resolves the NPSP Household Account record type Id from its
     *              DeveloperName using describe (no hard-coded record type Ids, so this
     *              works in any org/sandbox regardless of Id differences).
     * @return The Household record type Id.
     * @throws IllegalArgumentException if the record type does not exist or is not
     *         available for the running user.
     */
    private static Id getHouseholdRecordTypeId() {
        Schema.RecordTypeInfo householdInfo = Account.SObjectType.getDescribe()
            .getRecordTypeInfosByDeveloperName()
            .get(HOUSEHOLD_RECORD_TYPE_DEV_NAME);

        if (householdInfo == null || !householdInfo.isAvailable()) {
            throw new IllegalArgumentException(
                'The NPSP Household Account record type (DeveloperName "' +
                HOUSEHOLD_RECORD_TYPE_DEV_NAME +
                '") was not found or is not available for the current user.'
            );
        }

        return householdInfo.getRecordTypeId();
    }
}
