/**
 * NPSP Table-Driven Trigger Management (TDTM) trigger handler for Opportunity.
 *
 * Creates a high-priority follow-up Task when an Opportunity becomes a
 * "major gift": StageName = Closed Won and Amount >= 5,000.
 *
 *   - AfterInsert: the record is Closed Won with Amount >= 5,000.
 *   - AfterUpdate: the record became Closed Won with Amount >= 5,000 and was
 *     NOT already both of those before the update, so editing a gift that
 *     already qualified never creates a duplicate task.
 *
 * Registration (done by the admin, no code required):
 *   npsp__Trigger_Handler__c
 *     npsp__Class__c          = OPP_MajorGiftFollowUp_TDTM
 *     npsp__Object__c         = Opportunity
 *     npsp__Trigger_Action__c = AfterInsert;AfterUpdate
 *     npsp__Load_Order__c     = 5
 *     npsp__Is_Active__c      = checked (unchecked = handler stops running)
 *
 * Deactivation: NPSP's TDTM dispatcher (npsp.TDTM_Global_API) reads the
 * Trigger Handler records on every transaction and only invokes handlers on
 * ACTIVE records, so unchecking the handler record under NPSP Settings >
 * Trigger Configuration stops this class from running. No guard code needed.
 *
 * IMPORTANT: this class and the overridden run() method must be declared
 * `global`. NPSP's TDTM dispatcher executes inside the npsp managed package
 * and invokes the handler through the base-class reference; Apex only allows
 * managed-package code to call members on classes outside its namespace when
 * those members are declared global. A `public` handler is silently never
 * invoked by the dispatcher, which is why the class visibility matters here.
 *
 * Limits: 0 SOQL queries and 1 DML statement per transaction. Everything the
 * handler needs (OwnerId, npsp__Primary_Contact__c, CloseDate) is already on
 * the trigger records, so no queries are required. Fully bulk-safe: 200+
 * opportunities are processed with a single Task insert.
 */
global without sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    private static final Decimal MAJOR_GIFT_MIN_AMOUNT = 5000;
    private static final String CLOSED_WON_STAGE = 'Closed Won';
    private static final String TASK_SUBJECT = 'Major gift thank-you call';
    private static final String TASK_PRIORITY = 'High';
    private static final String TASK_STATUS = 'Not Started';
    private static final Integer FOLLOW_UP_OFFSET_DAYS = 3;

    /**
     * Entry point called by NPSP's TDTM dispatcher for every enabled
     * Trigger Handler record. Must be global (see class comment).
     *
     * Returns null: this handler performs its own DML (exactly one insert
     * statement) and hands nothing back to TDTM_Table for further processing.
     */
    global override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        // Defensive: only process Opportunity in the after insert / after
        // update phases this handler is registered for.
        Boolean isAfterInsert =
            triggerAction == npsp.TDTM_Runnable.Action.AfterInsert;
        Boolean isAfterUpdate =
            triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate;
        if (objResult == null
                || objResult.getName() != 'Opportunity'
                || newlist == null
                || newlist.isEmpty()
                || (!isAfterInsert && !isAfterUpdate)) {
            return null;
        }

        List<Task> followUpTasks = new List<Task>();

        // Trigger.new and Trigger.old are index-aligned, so a single indexed
        // loop handles both phases and the whole batch (200+ records).
        for (Integer i = 0; i < newlist.size(); i++) {
            Opportunity opp = (Opportunity) newlist[i];

            // On AfterUpdate, compare against the pre-update value so a task
            // is created only on the transition INTO "major gift". A record
            // that already qualified before the update is skipped (no
            // duplicates when editing an already-qualified gift).
            Opportunity oldOpp = null;
            if (isAfterUpdate
                    && oldlist != null
                    && oldlist.size() == newlist.size()) {
                oldOpp = (Opportunity) oldlist[i];
            }

            if (isMajorGift(opp) && (oldOpp == null || !isMajorGift(oldOpp))) {
                followUpTasks.add(buildFollowUpTask(opp));
            }
        }

        if (!followUpTasks.isEmpty()) {
            // Single DML statement for the whole batch. partial success keeps
            // a problem on an individual Task (e.g. an org-specific
            // validation rule) from rolling back the Opportunity save itself.
            Database.insert(followUpTasks, false);
        }

        return null;
    }

    /**
     * A record qualifies when its stage is exactly "Closed Won" and its
     * Amount is non-null and >= 5,000 (a null Amount never qualifies).
     */
    private static Boolean isMajorGift(Opportunity opp) {
        return opp.StageName == CLOSED_WON_STAGE
            && opp.Amount != null
            && opp.Amount >= MAJOR_GIFT_MIN_AMOUNT;
    }

    /**
     * Builds the follow-up Task from data already present on the Opportunity
     * record - no SOQL needed.
     */
    private static Task buildFollowUpTask(Opportunity opp) {
        Task followUp = new Task(
            Subject = TASK_SUBJECT,
            Priority = TASK_PRIORITY,
            Status = TASK_STATUS,
            // "What" = the Opportunity.
            WhatId = opp.Id,
            // Owner = the Opportunity owner (already on the record).
            OwnerId = opp.OwnerId
        );

        // The primary contact may be null; only set WhoId when present.
        if (opp.npsp__Primary_Contact__c != null) {
            followUp.WhoId = opp.npsp__Primary_Contact__c;
        }

        // Due date = CloseDate + 3 days; skipped if CloseDate is null.
        if (opp.CloseDate != null) {
            followUp.ActivityDate = opp.CloseDate.addDays(FOLLOW_UP_OFFSET_DAYS);
        }

        return followUp;
    }
}
```

The fix versus the previous attempt: NPSP's TDTM dispatcher runs inside the `npsp` managed package and invokes the handler through an `npsp.TDTM_Runnable` reference. Apex only permits managed-package code to call into a class from another namespace (the subscriber org) when that member is declared `global` — with a `public` class and `public override`, the dispatcher could not invoke `run()`, so the handler silently never executed and every test saw zero tasks. The class and the `run()` override are now declared `global` (the standard, documented pattern for custom TDTM handlers); the qualification, transition-detection, and bulk/limit behaviour are unchanged and correct (0 SOQL, 1 DML statement, duplicate-free on edits).

