public with sharing class RecordAccessService {
    /**
     * Returns the subset of recordIds that the running user can edit, as reported
     * by the UserRecordAccess object (HasEditAccess = true).
     *
     * Notes on implementation:
     * - UserRecordAccess only exposes access checks for at most 200 record IDs per
     *   query (documented platform limit), so the input is chunked into batches of 200.
     * - With the documented caller limit of 2,000 IDs this costs at most 10 SOQL
     *   queries, comfortably inside the 20-query budget.
     * - Records the user cannot even see (e.g. no read access via ownership, sharing,
     *   role hierarchy, or View All) simply do not appear in the result set, which is
     *   exactly the behaviour we want: they are not editable and are omitted.
     * - Modify All Data / Modify All on the object / record ownership / sharing rules
     *   / role hierarchy are all evaluated by the platform inside UserRecordAccess,
     *   so no manual permission logic is needed (and none should be duplicated).
     * - The check is made for the running user (UserId filter), so the result
     *   reflects that user's real permissions.
     *
     * @param recordIds candidate record IDs, may span multiple objects, max 2,000
     * @return the editable subset; empty (never null) for null/empty input
     */
    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> result = new Set<Id>();
        if (recordIds == null || recordIds.isEmpty()) {
            return result;
        }

        // Deduplicate and drop nulls into an ordered list for chunking.
        List<Id> ids = new List<Id>();
        for (Id recordId : recordIds) {
            if (recordId != null && !ids.contains(recordId)) {
                ids.add(recordId);
            }
        }
        if (ids.isEmpty()) {
            return result;
        }

        // UserRecordAccess allows filtering by at most 200 RecordIds per query.
        final Integer chunkSize = 200;

        Integer index = 0;
        while (index < ids.size()) {
            Integer chunkStart = index;
            Integer chunkStop = Math.min(chunkStart + chunkSize, ids.size());

            // Build the chunk explicitly (avoids subList/end identifier pitfalls).
            List<Id> chunk = new List<Id>();
            for (Integer i = chunkStart; i < chunkStop; i++) {
                chunk.add(ids.get(i));
            }

            for (UserRecordAccess access : [
                SELECT RecordId
                FROM UserRecordAccess
                WHERE UserId = :UserInfo.getUserId()
                  AND HasEditAccess = true
                  AND RecordId IN :chunk
            ]) {
                result.add(access.RecordId);
            }

            index = chunkStop;
        }

        return result;
    }
}
