/**
 * @description Service for reassigning books of business: sets the OwnerId on the
 *              given Accounts and on all Contacts of those Accounts.
 *
 *              Account trigger automation is bypassed for the duration of the
 *              ownership change using the Trigger Actions Framework (TAF)
 *              transaction-level sObject bypass, because Account trigger actions
 *              (territory recalculation) are expensive and must not run for this
 *              operation. Contact trigger actions run normally.
 *
 *              The bypass is always cleared in a `finally` block, so Account
 *              automation behaves normally for the rest of the transaction whether
 *              `reassign` succeeds or throws.
 *
 *              Bulk-safe: exactly one SOQL query and two all-or-none DML
 *              statements regardless of volume (callers pass up to 200 accounts).
 *              Exceptions propagate to the caller unchanged.
 *
 * @group       Services
 */
public inherited sharing class AccountOwnershipService {

    /**
     * @description Reassigns ownership of the given Accounts and their Contacts.
     * @param accountIds Ids of the Accounts to reassign. May contain up to 200 Ids.
     * @param newOwnerId Id of the User (or Queue) that becomes the new owner.
     */
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        // Defensive guard: nothing to do rather than attempting empty DML.
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Account DML does not require a query: an sObject with Id + OwnerId
        // is sufficient for an update. This keeps us at zero Account SOQL.
        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : accountIds) {
            accountsToUpdate.add(new Account(Id = accountId, OwnerId = newOwnerId));
        }

        // Single SOQL: all Contacts parented to the given Accounts.
        // (Query #1 of 2.)
        List<Contact> contactsToUpdate = [
            SELECT Id
            FROM Contact
            WHERE AccountId IN :accountIds
        ];
        for (Contact contact : contactsToUpdate) {
            contact.OwnerId = newOwnerId;
        }

        // Bypass the whole Account sObject in TAF so no Account trigger action
        // (before/after update) runs for this ownership change.
        // Note: TriggerBase is a top-level class in the package, not nested
        // inside TriggerAction, so it is referenced directly.
        TriggerBase.bypass(Schema.Account.SObjectType);
        try {
            // All-or-none DML (allOrNone defaults to true): any failure throws
            // and rolls back the whole statement, and the exception propagates
            // to the caller unchanged. (DML #1 of 2.)
            update accountsToUpdate;

            // Contact trigger actions run normally here — only Account is bypassed.
            // (DML #2 of 2.)
            update contactsToUpdate;
        } finally {
            // Always restore Account automation, on success and on failure,
            // so the rest of the transaction behaves normally.
            TriggerBase.clearBypass(Schema.Account.SObjectType);
        }
    }
}
