/**
 * Trigger Action (after insert / after update on Opportunity).
 *
 * Collects the Ids of every opportunity of the CURRENT DML operation that must
 * be pushed to the ERP:
 *   - after insert: every opportunity of the operation.
 *   - after update: every opportunity whose StageName changed.
 *
 * The Ids are accumulated in OpportunityErpSyncFinalizer so that they survive
 * trigger chunking (e.g. a 250-row insert fires this action in a 200 + 50
 * chunk), and the actual enqueueing is deferred to the OpportunityErpSyncFinalizer
 * DML finalizer, which runs exactly once per DML operation, after the statement
 * has completed. TriggerBase.waitToFinalize() is safe to call from every
 * trigger chunk; the framework only attaches its finalizer once.
 */
public inherited sharing class TA_Opportunity_CollectForErpSync
        implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate {

    public void afterInsert(List<SObject> triggerNew) {
        registerAll(triggerNew);
        TriggerBase.waitToFinalize();
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, SObject> oldRecordsById = new Map<Id, SObject>(triggerOld);
        List<SObject> stageChangedRecords = new List<SObject>();
        for (SObject record : triggerNew) {
            Opportunity newRecord = (Opportunity) record;
            Opportunity oldRecord = (Opportunity) oldRecordsById.get(record.Id);
            if (oldRecord != null && newRecord.StageName != oldRecord.StageName) {
                stageChangedRecords.add(record);
            }
        }
        registerAll(stageChangedRecords);
        TriggerBase.waitToFinalize();
    }

    private void registerAll(List<SObject> records) {
        for (SObject record : records) {
            OpportunityErpSyncFinalizer.registerOpportunityId(record.Id);
        }
    }
}
