/**
 * DML Finalizer that enqueues exactly ONE OpportunityErpSyncJob per DML
 * operation, carrying the Ids of every opportunity of that operation that
 * needs to be synced, and no job at all when none does.
 *
 * The framework calls every registered DML finalizer at the end of EVERY DML
 * operation it handles, whatever the sObject. Therefore this class does
 * nothing when no Ids have been collected for the current DML operation, and
 * it clears the collected Ids after enqueueing so that subsequent invocations
 * (e.g. for a second DML statement in the same transaction, or for DML on
 * other sObjects) produce their own job, or nothing at all.
 *
 * Finalizers must not perform DML: this class only reads its static state and
 * enqueues a Queueable, which is safe.
 */
public inherited sharing class OpportunityErpSyncFinalizer
        implements TriggerAction.DmlFinalizer {

    /**
     * Ids collected by TA_Opportunity_CollectForErpSync for the current DML
     * operation. Accumulates across the trigger chunks of the same DML
     * statement (e.g. 200 + 50) so that a single job carries all of them.
     */
    @TestVisible
    private static Set<Id> opportunityIdsToSync = new Set<Id>();

    public static void registerOpportunityId(Id opportunityId) {
        opportunityIdsToSync.add(opportunityId);
    }

    public static void registerOpportunityIds(Set<Id> opportunityIds) {
        opportunityIdsToSync.addAll(opportunityIds);
    }

    public void execute(FinalizerHandler.Context context) {
        // The framework calls this finalizer at the end of every DML operation
        // it handles, whatever the sObject. Nothing to sync means no job.
        if (opportunityIdsToSync.isEmpty()) {
            return;
        }
        // Snapshot the Ids of this DML operation, then reset the state so that
        // the next DML operation in the transaction gets its own job (and so
        // that any further invocation in this transaction is a no-op).
        Set<Id> idsForThisDml = new Set<Id>(opportunityIdsToSync);
        opportunityIdsToSync.clear();
        System.enqueueJob(new OpportunityErpSyncJob(idsForThisDml));
    }
}
