/**
 * @description Sets Case Priority based on the Subject ('urgent' => 'High')
 * and falls back to 'Low' for web-originated cases.
 * Must run after TA_Case_DefaultOrigin in the before insert context,
 * because it relies on the Origin default having been applied.
 */
public inherited sharing class TA_Case_SetPriority implements TriggerAction.BeforeInsert {

    private static final String HIGH_PRIORITY = 'High';
    private static final String LOW_PRIORITY = 'Low';
    private static final String WEB_ORIGIN = 'Web';
    private static final String URGENT_KEYWORD = 'urgent';

    public void beforeInsert(List<SObject> triggerNew) {
        List<Case> newCases = (List<Case>) triggerNew;
        for (Case c : newCases) {
            if (c.Subject != null && c.Subject.containsIgnoreCase(URGENT_KEYWORD)) {
                c.Priority = HIGH_PRIORITY;
            } else if (c.Origin == WEB_ORIGIN) {
                c.Priority = LOW_PRIORITY;
            }
        }
    }
}
