/**
 * @description Adds a comment to Cases that transition to Closed status.
 * Registered on the Case sObject Trigger Setting for the after update context.
 * Bulk-safe: all comments are collected and inserted in a single DML statement.
 */
public inherited sharing class TA_Case_AddClosureComment implements TriggerAction.AfterUpdate {

    private static final String CLOSED_STATUS = 'Closed';
    private static final String COMMENT_PREFIX = 'Case closed on ';

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Case> newCases = (List<Case>) triggerNew;
        Map<Id, Case> oldCases = new Map<Id, Case>((List<Case>) triggerOld);
        List<CaseComment> comments = new List<CaseComment>();
        for (Case c : newCases) {
            Case oldCase = oldCases.get(c.Id);
            if (c.Status == CLOSED_STATUS && oldCase.Status != CLOSED_STATUS) {
                comments.add(new CaseComment(
                    ParentId = c.Id,
                    CommentBody = COMMENT_PREFIX + String.valueOf(Date.today()),
                    IsPublished = false
                ));
            }
        }
        if (!comments.isEmpty()) {
            insert comments;
        }
    }
}
